            var snapshot = new ProviderSnapshot(source.Refusal, provenance, revision, sections.ToImmutable(), source.Identity, documentPresent, providerEntities.ToImmutable(), providerEntitiesByKey, configurationsEntities.ToImmutable(), configurationsEntitiesByKey, engagementsEntities.ToImmutable(), engagementsEntitiesByKey);

            snapshot.Diagnostics = context.Diagnostics;
            snapshot.Availability = context.HasErrors ? SemanticAvailability.ContractMismatch : refused ?? (declaredAbsent ? SemanticAvailability.Absent : SemanticAvailability.Present);
            try
            {
                snapshot.ProjectionDigest = "sha256:" + SemanticCanonicalJson.Sha256Hex(snapshot.ToCanonicalPayload());
            }
            catch (InvalidOperationException exception)
            {
                context.Report("PayloadNotCanonical", SemanticSeverity.Error, null, null, null, "The projection payload cannot be canonicalized: " + exception.Message);
                snapshot.Diagnostics = context.Diagnostics;
                snapshot.Availability = SemanticAvailability.ContractMismatch;
            }

            return snapshot;
        }

