            writer.WriteString("object_kind", entity.ObjectKind);
            writer.WriteString("namespace_id", entity.NamespaceId);
            writer.WriteString("declared_name", entity.DeclaredName);
            writer.WriteString("provider_role", entity.ProviderRole);
            writer.WriteString("definition_digest", entity.DefinitionDigest);
            writer.WriteString("engagement_kinds", entity.EngagementKinds);
            if (entity.Engagements is { } v9)
