            else
            {
                writer.WriteNull("shared_authority_references");
            }
            foreach (SemanticField field in entity.UnmappedFields)
            {
                SemanticWriting.Raw(writer, field.Name, field.Value);
            }

            writer.WriteEndObject();
        }

