        /// <summary>The canonical projection payload that ProjectionDigest hashes: contract identity, bound source arguments and reader definition digest, availability, every section and row, and every diagnostic (without messages). Capture time, duration and generator are excluded.</summary>
        public string ToCanonicalPayload()
        {
            var payload = new SemanticCanonicalObject()
                .Add("projection", "semantic-projection.v1")
                .Add("profile", "full")
                .Add("contract", new SemanticCanonicalObject().Add("id", ProviderProjectionContract.Id).Add("revision", ProviderProjectionContract.Revision).Add("digest", ProviderProjectionContract.Digest))
                .Add("source", new SemanticCanonicalObject()
                    .Add("procedure", Provenance.Procedure)
                    .Add("arguments", SemanticPayload.Arguments(Provenance.Arguments))
                    .Add("readerDefinitionDigest", Provenance.Capture.ReaderDefinitionDigest)
                    .Add("revisionDigest", Revision.RevisionDigest)
                    .Add("resultSets", SemanticPayload.ResultSets(Provenance.ResultSets)))
                .Add("availability", Availability.ToString())
                .Add("refusal", SemanticPayload.Refusal(Refusal))
                .Add("sections", Sections.Select(section => SemanticPayload.Section(section, row => CanonicalEntity(section.Name, row.EntityOrdinal!.Value))).ToList())
                .Add("diagnostics", SemanticPayload.Diagnostics(Diagnostics, Sections));
            return SemanticCanonicalJson.Serialize(payload);
        }

