        /// <summary>A bounded, human- and agent-readable view: identity, availability, provenance, coverage, up to <paramref name="maxEntitiesPerSection"/> entities per typed section with reference states, and diagnostics. Omissions are counted, never silent.</summary>
        public string ToInspectionJson(int maxEntitiesPerSection = 25, int maxDiagnostics = 200)
